import numpy as np
from vispy import app, gloo
from vispy.util import keys
import time

VERT_SHADER = """
#version 120
uniform float u_time;
uniform vec2 u_center;
uniform float u_explosion_time;
attribute vec2 a_position;
attribute vec3 a_color;
attribute float a_angle;
attribute float a_speed;
attribute float a_lifetime;
varying vec3 v_color;
void main()
{
    float t = clamp(u_time - u_explosion_time, 0.0, a_lifetime);
    float fade = 1.0 - t / a_lifetime;
    float r = t * a_speed;
    vec2 pos = u_center + vec2(cos(a_angle), sin(a_angle)) * r;
    gl_Position = vec4(2.0 * pos.x - 1.0, 2.0 * pos.y - 1.0, 0.0, 1.0);
    gl_PointSize = 3.0 * fade;
    v_color = a_color * fade;
}
"""

FRAG_SHADER = """
#version 120
varying vec3 v_color;
void main()
{
    float d = length(gl_PointCoord - vec2(0.5, 0.5));
    if (d > 0.5)
        discard;
    gl_FragColor = vec4(v_color, 1.0 - d);
}
"""

def random_colors(n):
    hsv = np.zeros((n, 3), dtype=np.float32)
    hsv[:, 0] = np.random.rand(n)
    hsv[:, 1] = 0.7 + 0.3 * np.random.rand(n)
    hsv[:, 2] = 0.8 + 0.2 * np.random.rand(n)
    rgb = np.zeros((n, 3), dtype=np.float32)
    for i in range(n):
        h, s, v = hsv[i]
        i_h = int(h * 6.0)
        f = h * 6.0 - i_h
        p = v * (1.0 - s)
        q = v * (1.0 - f * s)
        t = v * (1.0 - (1.0 - f) * s)
        i_h = i_h % 6
        if i_h == 0:
            rgb[i] = [v, t, p]
        elif i_h == 1:
            rgb[i] = [q, v, p]
        elif i_h == 2:
            rgb[i] = [p, v, t]
        elif i_h == 3:
            rgb[i] = [p, q, v]
        elif i_h == 4:
            rgb[i] = [t, p, v]
        elif i_h == 5:
            rgb[i] = [v, p, q]
    return rgb

class Canvas(app.Canvas):
    def __init__(self):
        app.Canvas.__init__(self, keys='interactive', size=(800, 600), title='Vispy Fireworks')
        self.program = gloo.Program(VERT_SHADER, FRAG_SHADER)
        self.n_particles = 0
        self.max_particles = 200
        self.explosions = []
        self.t0 = time.time()
        self.u_time = 0.0
        self._timer = app.Timer('auto', connect=self.on_timer, start=True)
        self.create_explosion()
        self.show()

    def create_explosion(self, center=None):
        n = np.random.randint(60, self.max_particles)
        if center is None:
            center = np.random.uniform([0.1, 0.2], [0.9, 0.8])
        angles = np.linspace(0, 2 * np.pi, n, endpoint=False) + np.random.uniform(-0.05, 0.05, n)
        speeds = np.random.uniform(0.25, 0.5, n)
        lifetimes = np.random.uniform(0.7, 1.0, n)
        colors = random_colors(n)
        explosion = {
            'center': np.array(center, dtype=np.float32),
            'angles': angles.astype(np.float32),
            'speeds': speeds.astype(np.float32),
            'colors': colors,
            'lifetimes': lifetimes.astype(np.float32),
            'start_time': self.u_time,
            'n': n
        }
        self.explosions.append(explosion)
        if len(self.explosions) > 5:
            self.explosions.pop(0)

    def on_draw(self, event):
        gloo.clear('black')
        now = self.u_time
        for explosion in self.explosions:
            t = now - explosion['start_time']
            mask = t < explosion['lifetimes'].max()
            if not mask:
                continue
            n = explosion['n']
            data = np.zeros(n, dtype=[('a_position', np.float32, 2),
                                      ('a_angle', np.float32, 1),
                                      ('a_speed', np.float32, 1),
                                      ('a_color', np.float32, 3),
                                      ('a_lifetime', np.float32, 1)])
            data['a_position'][:] = explosion['center']
            data['a_angle'][:] = explosion['angles']
            data['a_speed'][:] = explosion['speeds']
            data['a_color'][:] = explosion['colors']
            data['a_lifetime'][:] = explosion['lifetimes']
            self.program['u_time'] = now
            self.program['u_center'] = explosion['center']
            self.program['u_explosion_time'] = explosion['start_time']
            self.program.bind(gloo.VertexBuffer(data))
            self.program.draw('points')

    def on_resize(self, event):
        gloo.set_viewport(0, 0, *event.size)

    def on_timer(self, event):
        self.u_time = time.time() - self.t0
        # Remove finished explosions
        self.explosions = [e for e in self.explosions if self.u_time - e['start_time'] < e['lifetimes'].max()]
        # Add new explosion every ~1s
        if not self.explosions or (self.u_time - self.explosions[-1]['start_time'] > 1.0):
            self.create_explosion()
        self.update()

    def on_mouse_press(self, event):
        pos = event.pos
        w, h = self.size
        center = (pos[0] / w, 1.0 - pos[1] / h)
        self.create_explosion(center=center)

    def on_key_press(self, event):
        if event.key in (keys.ESCAPE, 'Q'):
            self.close()

if __name__ == '__main__':
    c = Canvas()
    app.run()
